using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Trait("Category", "Acceptance")]
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]
    [InlineData(LoyaltyTier.Green, 10_000, 9_400)]
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Gold, 19_999, 18_400)]
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var useCase = new CalculatePayableTotal();
        var actualCheckoutTotal = useCase.For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, actualCheckoutTotal);
    }
}
namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    public static int CalculatePayableTotal(int subtotalCents, LoyaltyTier loyaltyTier)
    {
        var baseRate = loyaltyTier switch
        {
            LoyaltyTier.Green => 5,
            LoyaltyTier.Gold => 7,
            LoyaltyTier.Platinum => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier), loyaltyTier, null),
        };

        var bonusRate = subtotalCents switch
        {
            >= 20_000 => 3,
            >= 5_000 => 1,
            _ => 0,
        };
        var effectiveRate = Math.Min(baseRate + bonusRate, 10);
        var discountCents = subtotalCents * effectiveRate / 100;

        return subtotalCents - discountCents;
    }
}
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public int For(int subtotalCents, LoyaltyTier loyaltyTier)
    {
        return LoyaltyDiscountPolicy.CalculatePayableTotal(subtotalCents, loyaltyTier);
    }
}
